-- composition of rule kernels common_aggregate x unused_columns (duckdb), template product
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ['a', 'b']::text[] AS c0, 10.0::float8 AS c1, a1.c3 AS c2 FROM t3 AS a1 UNION ALL SELECT ARRAY['1'::text] AS c0, 10.0::float8 AS c1, '00:00:00.000001'::interval AS c2) AS ka CROSS JOIN (SELECT '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c0, 0.5::numeric AS c1, 1::bigint AS c2, 'a'::text AS c3 FROM t3 AS a1 HAVING BOOL_AND ((a1.c5 < ANY (SELECT 'NaN'::text AS c0)))) AS kb;
-- pgfuzz:check kernel:product SELECT (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ['a', 'b']::text[] AS c0, 10.0::float8 AS c1, a1.c3 AS c2 FROM t3 AS a1 UNION ALL SELECT ARRAY['1'::text] AS c0, 10.0::float8 AS c1, '00:00:00.000001'::interval AS c2) AS ka) * (SELECT count(*) FROM (SELECT '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c0, 0.5::numeric AS c1, 1::bigint AS c2, 'a'::text AS c3 FROM t3 AS a1 HAVING BOOL_AND ((a1.c5 < ANY (SELECT 'NaN'::text AS c0)))) AS kb)
